a:=('[{"relation":"works","ref":"canonical-library-work","key":{"id":991880009},"before":{"id":991880009,"title":"Almost Transparent Blue","author_id":991900009,"first_publish_year":2003,"open_library_id":"OL7989537W","cover_id":null,"source_type":null,"work_type":null,"native_identity_key":null},"after":{"id":991880009,"title":"Almost Transparent Blue","author_id":991900009,"first_publish_year":2003,"open_library_id":"OL3741471W","cover_id":null,"source_type":null,"work_type":null,"native_identity_key":null}},{"relation":"catalog_work_descriptions","ref":"summary-2093","key":{"work_id":991880002,"language":"en"},"before":null,"after":{"work_id":991880002,"language":"en","bound_author_id":991900002,"text":"John Stuart Mill examines when society and government may restrict a person''s freedom. He argues that preventing harm to others can justify intervention, while disagreement or disapproval alone cannot. The essay considers freedom of thought and discussion, individual ways of living, and the pressure exerted by public opinion. Rather than telling a fictional story, it develops an argument about the limits of authority and the value of allowing different views to be heard.","source_type":"official_catalog","source_name":"Project Gutenberg — original text","source_url":"https://www.gutenberg.org/cache/epub/34901/pg34901-images.html","evidence":[{"url":"https://www.gutenberg.org/cache/epub/34901/pg34901-images.html","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Original English text, chapters on thought/discussion, individuality and limits of authority; not the generated catalogue blurb.","Edition ISBN and author independently bound through OL7925728M; no new language inference."]},{"url":"https://openlibrary.org/books/OL7925728M.json","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Exact ISBN/title/language and bibliographic identity reviewed; synopsis is an original Work-level text, not an edition-language inference."]}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-07T16:54:59.393Z","review_batch":"verified-synopses-20261107"}},{"relation":"catalog_work_descriptions","ref":"summary-3137","key":{"work_id":991880003,"language":"en"},"before":null,"after":{"work_id":991880003,"language":"en","bound_author_id":987339006,"text":"In 1946 Mississippi, respected farmer and war veteran Pete Banning kills a local minister, then refuses to explain why. His silence leaves his family, lawyers and neighbours struggling to understand an apparently senseless act. As the case moves through the courts, the novel turns back to Pete''s wartime experiences and the history of his family. The question of motive connects the public trial with events that those around him do not fully understand.","source_type":"official_publisher","source_name":"Penguin Random House","source_url":"https://www.penguinrandomhouse.com/books/586399/the-reckoning-by-john-grisham/","evidence":[{"url":"https://www.penguinrandomhouse.com/books/586399/the-reckoning-by-john-grisham/","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Pete Banning, Clanton1946, killing and refusal to explain, court/family/WWII narrative verified by publisher.","Publisher international newsletter2020 explicitly pairs The Reckoning with ISBN9781984819956; adjacent A Time for Mercy text is not this ISBN."]},{"url":"https://openlibrary.org/books/OL35674672M.json","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Exact ISBN/title/language and bibliographic identity reviewed; synopsis is an original Work-level text, not an edition-language inference."]}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-07T16:54:59.393Z","review_batch":"verified-synopses-20261107"}},{"relation":"catalog_work_descriptions","ref":"summary-4182","key":{"work_id":991880004,"language":"en"},"before":null,"after":{"work_id":991880004,"language":"en","bound_author_id":991900004,"text":"Ravin and Khushi meet through a matrimonial website and begin getting to know one another at a distance. Calls and messages gradually turn an initial introduction into a relationship, and they start imagining a future together. Drawing on the author''s own experience, the novel follows the hopes and emotional vulnerability that accompany their plans. Their story confronts the possibility that a deeply felt love may not have the ending the couple expects.","source_type":"official_publisher","source_name":"Penguin Random House India","source_url":"https://www.penguin.co.in/book/i-too-had-a-love-story/","evidence":[{"url":"https://www.penguin.co.in/book/i-too-had-a-love-story/","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Exact9780143418764, Ravinder Singh and English original verified.","Publisher names Ravin/Khushi, matrimonial website, true-life basis and relationship tested by loss; no ending disclosed."]},{"url":"https://openlibrary.org/books/OL36645820M.json","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Exact ISBN/title/language and bibliographic identity reviewed; synopsis is an original Work-level text, not an edition-language inference."]}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-07T16:54:59.393Z","review_batch":"verified-synopses-20261107"}},{"relation":"catalog_work_descriptions","ref":"summary-5226","key":{"work_id":991880005,"language":"nl"},"before":null,"after":{"work_id":991880005,"language":"nl","bound_author_id":991900005,"text":"Mirjam Blits vertelt hoe zij en haar man in februari 1943 worden opgepakt en hoe zij de Duitse concentratiekampen doorstaat. Na haar terugkeer in Amsterdam begint zij haar ervaringen op te schrijven, terwijl zij het verlies van haar man en familie onder ogen moet zien. Haar herinneringen gaan over geweld en ontbering, maar ook over de steun tussen meisjes en jonge vrouwen. Zo legt zij vast hoe zij elkaar tijdens de gevangenschap proberen overeind te houden.","source_type":"official_publisher","source_name":"Just Publishers","source_url":"https://justpublishers.nl/project/auschwitz-13917/","evidence":[{"url":"https://justpublishers.nl/project/auschwitz-13917/","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Author, arrest25Feb1943 with husband, return Amsterdam and writing verified.","Female-prisoner solidarity and losses verified; no2020foreword facts transferred into2012edition."]},{"url":"https://openlibrary.org/books/OL43872702M.json","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Exact ISBN/title/language and bibliographic identity reviewed; synopsis is an original Work-level text, not an edition-language inference."]}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-07T16:54:59.393Z","review_batch":"verified-synopses-20261107"}},{"relation":"catalog_work_descriptions","ref":"summary-7315","key":{"work_id":991880006,"language":"en"},"before":null,"after":{"work_id":991880006,"language":"en","bound_author_id":991900006,"text":"Ronald M. Baecker examines how digital technologies influence everyday life and the institutions around us. The book considers computing in education, health, media, government and conflict, then weighs questions of privacy, security, inclusion and employment. Artificial intelligence is discussed alongside the choices people make about designing and using technology. The emphasis is on social and ethical consequences, helping readers consider both the benefits of computing and the problems it can create.","source_type":"official_publisher","source_name":"Oxford University Press","source_url":"https://academic.oup.com/book/41802","evidence":[{"url":"https://academic.oup.com/book/41802","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Author/title and abstract scope verified with Oxford.","Exact paperback9780198827092 verified separately by Oxford India/CiNii; abstract hardcoverISBN is same underlying work, not a format correction."]},{"url":"https://openlibrary.org/books/OL28718461M.json","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Exact ISBN/title/language and bibliographic identity reviewed; synopsis is an original Work-level text, not an edition-language inference."]}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-07T16:54:59.393Z","review_batch":"verified-synopses-20261107"}},{"relation":"catalog_work_descriptions","ref":"summary-8359","key":{"work_id":991880008,"language":"en"},"before":null,"after":{"work_id":991880008,"language":"en","bound_author_id":991900008,"text":"Alice Miller argues that painful childhood experiences can continue to affect adult emotional and physical life. Drawing on personal histories and examples from writers'' lives, she examines the tension between remembered suffering and the expectation that children should honour or forgive their parents. The book presents Miller''s views on recognising earlier harm and listening to one''s feelings. She contrasts demands for family loyalty with the need to acknowledge a child''s experience.","source_type":"official_publisher","source_name":"W. W. Norton","source_url":"https://wwnorton.co.uk/books/9780393328639-the-body-never-lies","evidence":[{"url":"https://wwnorton.co.uk/books/9780393328639-the-body-never-lies","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Alice Miller, English translation Andrew Jenkins and same work confirmed.","Childhood trauma, biographical examples and duty/forgiveness argument are attributed to author, not presented as established disease causation."]},{"url":"https://openlibrary.org/books/OL7452083M.json","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Exact ISBN/title/language and bibliographic identity reviewed; synopsis is an original Work-level text, not an edition-language inference."]}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-07T16:54:59.393Z","review_batch":"verified-synopses-20261107"}},{"relation":"catalog_work_descriptions","ref":"summary-8856","key":{"work_id":991880009,"language":"en"},"before":null,"after":{"work_id":991880009,"language":"en","bound_author_id":991900009,"text":"Ryū Murakami depicts a circle of young friends living in a Japanese town near an American military base. Drug use, sexual encounters and episodes of violence shape their routines and strain their connections with one another. The novel uses sharply focused physical sensations and fragmented experiences to portray their unstable world. Its subject is the destructive pattern of these lives and the difficulty of finding a lasting sense of connection.","source_type":"official_catalog","source_name":"Google Books / Kodansha bibliographic record","source_url":"https://books.google.com/books/about/Almost_Transparent_Blue.html?id=Qwc9zwEACAAJ","evidence":[{"url":"https://books.google.com/books/about/Almost_Transparent_Blue.html?id=Qwc9zwEACAAJ","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Publisher-supplied catalogue description identifies same novel, young friends, military-base setting and destructive routines.","CiNiiBA61502662 binds exact2003English tradepaperback9784770029041, RyūMurakami/NancyAndrew; other1977ISBN is only narrative corroboration."]},{"url":"https://openlibrary.org/books/OL9037490M.json","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Exact ISBN/title/language and bibliographic identity reviewed; synopsis is an original Work-level text, not an edition-language inference."]}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-07T16:54:59.393Z","review_batch":"verified-synopses-20261107"}},{"relation":"catalog_work_descriptions","ref":"summary-9050","key":{"work_id":991880010,"language":"en"},"before":null,"after":{"work_id":991880010,"language":"en","bound_author_id":991900010,"text":"When Mark leaves Alexa to marry her best friend, her plans for the future collapse. His brother Scott Kelsey is concerned about the effect of the scandal on the family''s reputation. Alexa then marries Scott as a way of saving face, despite the hurt surrounding the arrangement. The story follows a relationship formed in the shadow of another man''s rejection, with family expectations and Alexa''s unresolved feelings at its centre.","source_type":"official_catalog","source_name":"South Dakota State Library — 1990 bibliography","source_url":"https://files.eric.ed.gov/fulltext/ED337172.pdf","evidence":[{"url":"https://files.eric.ed.gov/fulltext/ED337172.pdf","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Library annotation PDFpage218 explicitly identifies SallyWentworth/Jilted and Alexa marryingScott afterMark marriesbestfriend.","ExactHarlequin1983paperback9780373106141 bound by OL10738224M; different largeprintedition is used only for shared plot, not edition facts."]},{"url":"https://openlibrary.org/books/OL10738224M.json","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Exact ISBN/title/language and bibliographic identity reviewed; synopsis is an original Work-level text, not an edition-language inference."]}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-07T16:54:59.393Z","review_batch":"verified-synopses-20261107"}},{"relation":"catalog_work_descriptions","ref":"summary-9404","key":{"work_id":991880011,"language":"en"},"before":null,"after":{"work_id":991880011,"language":"en","bound_author_id":991900011,"text":"After their father is murdered, the Locke children and their mother leave California for the family''s old house in Massachusetts. At Keyhouse, grief and a fresh start become entangled with doors and keys that have extraordinary powers. The youngest child begins discovering what those powers can do, while a dangerous presence has its own interest in the house. This opening graphic-novel volume introduces the family and the mysteries surrounding their inheritance.","source_type":"official_publisher","source_name":"Subterranean Press — same graphic novel","source_url":"https://subterraneanpress.com/locke-key-welcome-to-lovecraft/","evidence":[{"url":"https://subterraneanpress.com/locke-key-welcome-to-lovecraft/","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Same WelcomeToLovecraft graphic-novel story by JoeHill/GabrielRodriguez, not TV adaptation.","OriginalIDW9781600102370 exactISBN verified by PublishersWeekly and OL; SubPressscript extras/ISBN not imported as originaledition facts."]},{"url":"https://openlibrary.org/books/OL23106590M.json","checkedAt":"2026-11-07T16:54:59.393Z","facts":["Exact ISBN/title/language and bibliographic identity reviewed; synopsis is an original Work-level text, not an edition-language inference."]}],"provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-07T16:54:59.393Z","review_batch":"verified-synopses-20261107"}}]'::jsonb)->((r->>'seq')::integer-1);
if a is null or r->>'relation' is distinct from a->>'relation' or r->'key' is distinct from a->'key' or r->'before_row' is distinct from a->'before' then raise exception 'Receipt outside exact reviewed scope';end if;
execute format('select to_jsonb(jsonb_populate_record(null::public.%I,$1))',a->>'relation') into expected using a->'after';
if r->'after_row' is distinct from expected then raise exception 'Receipt content differs from proposal';end if;end loop;
if (select count(distinct value->>'seq') from jsonb_array_elements(receipt->'rows'))<>10 then raise exception 'Duplicate receipt sequence';end if;
end;$receipt_scope$;
do $undo$ declare receipt jsonb;r jsonb;actual jsonb;dep record;n bigint;cols text;k jsonb;predicate text;allowed_keys text[];begin
 receipt:=nullif(current_setting('lumiscore.catalog_release_receipt',true),'')::jsonb;
 if receipt->>'project' is distinct from 'hlvujbrmfdlrfxdjwsmb' or receipt->>'batch' is distinct from 'verified-synopses-20261107-test' or jsonb_typeof(receipt->'rows') is distinct from 'array' or jsonb_array_length(receipt->'rows')<>10 then raise exception 'Exact first committed receipt required';end if;
 for r in select value from jsonb_array_elements(receipt->'rows') order by (value->>'seq')::integer desc loop
  if r->>'relation' not in ('authors','works','editions','catalog_work_descriptions','catalog_edition_metadata') then raise exception 'Unreviewed receipt relation';end if;
  k:=r->'key';allowed_keys:=case r->>'relation' when 'authors' then array['id','open_library_id'] when 'works' then array['id','native_identity_key','open_library_id'] when 'editions' then array['id','open_library_edition_id','isbn_13','isbn_10'] when 'catalog_work_descriptions' then array['work_id','language'] else array['edition_id'] end;
  if jsonb_typeof(k)<>'object' or not exists(select 1 from jsonb_each(k)) or exists(select 1 from jsonb_each(k) where not key=any(allowed_keys) or value='null'::jsonb) then raise exception 'Invalid receipt identity key';end if;
  select string_agg(format('t.%I=(jsonb_populate_record(null::public.%I,$1)).%I',key,r->>'relation',key),' and ' order by key) into predicate from jsonb_each(k);
  execute format('select to_jsonb(t) from public.%I t where %s for update',r->>'relation',predicate) into actual using k;
  if actual is null and r->'before_row'='null'::jsonb then continue;end if;
  if actual is not distinct from r->'before_row' then continue;end if;
  if actual is distinct from r->'after_row' then raise exception 'Later legitimate change; recovery refused';end if;
  if r->'before_row'='null'::jsonb then
   for dep in select ns.nspname,c.relname,string_agg(format('(to_jsonb(child)->%L)=($1->%L)',ca.attname,pa.attname),' and ' order by k.ord) predicate
    from pg_constraint f join pg_class c on c.oid=f.conrelid join pg_namespace ns on ns.oid=c.relnamespace
    cross join lateral unnest(f.conkey,f.confkey) with ordinality k(childkey,parentkey,ord)
    join pg_attribute ca on ca.attrelid=f.conrelid and ca.attnum=k.childkey join pg_attribute pa on pa.attrelid=f.confrelid and pa.attnum=k.parentkey
    where f.contype='f' and f.confrelid=to_regclass('public.'||(r->>'relation')) group by f.oid,ns.nspname,c.relname
   loop
    execute format('select count(*) from %I.%I child where %s',dep.nspname,dep.relname,dep.predicate) into n using r->'after_row';
    if n>0 then raise exception 'Later dependency in %.%; recovery refused',dep.nspname,dep.relname;end if;
   end loop;
   execute format('delete from public.%I t where %s',r->>'relation',predicate) using k;
  else
   select string_agg(format('%I=(jsonb_populate_record(null::public.%I,$1)).%I',key,r->>'relation',key),',') into cols from jsonb_each(r->'before_row') where value is distinct from r->'after_row'->key;
   execute format('update public.%I t set %s where %s',r->>'relation',cols,replace(predicate,'$1','$2')) using r->'before_row',k;
  end if;
 end loop;
end;$undo$;commit;
